from cardio_1 import a, G
# R05 — Toux (P-02-Pneumologie). Abréviations nouvelles du cours, définition littérale lettre à lettre.
a('DGP',[('D','Deutsche'),('G','Gesellschaft für'),('P','Pneumologie (und Beatmungsmedizin)')],'Deutsche Gesellschaft für Pneumologie und Beatmungsmedizin (Société allemande de pneumologie et de ventilation)','<p>Société savante allemande de pneumologie. Sa recommandation S2k sur le diagnostic et le traitement de la toux de l’adulte (version longue 4.1, janvier 2025, registre AWMF 020-003) sert de référence germanophone au cours R05.</p>')
a('BTS',[('B','British'),('T','Thoracic'),('S','Society')],'British Thoracic Society (Société thoracique britannique)','<p>Société savante britannique de pneumologie ; elle a publié en 2023 une prise de position clinique sur la toux chronique de l’adulte (Thorax 2023;78 suppl. 6).</p>')
a('FDA',[('F','Food and'),('D','Drug'),('A','Administration')],'Food and Drug Administration (agence américaine des produits alimentaires et des médicaments)','<p>Autorité fédérale américaine qui autorise la mise sur le marché des médicaments aux États-Unis ; son autorisation ou son refus ne vaut pas décision en Suisse. Elle a refusé le géfapixant en décembre 2023.</p>')
a('XVIII',[('XVIII','dix-huit en chiffres romains')],'Chapitre 18 de la CIM-10-GM','<p>Chapitre « Symptômes, signes et résultats anormaux d’examens cliniques et de laboratoire, non classés ailleurs » (codes R00 à R99).</p>')
a('U69.6',[('U','chapitre XXII, codes à usage particulier'),('69.6','sous-catégorie toux chronique idiopathique ou réfractaire')],'Code supplémentaire de la toux chronique idiopathique ou réfractaire (CIM-10-GM)','<p>Code à point d’exclamation (code secondaire) qui s’ajoute à R05 pour signaler une toux chronique inexpliquée ou réfractaire. Il ne s’emploie jamais seul.</p>')
a('R04.2',[('R','chapitre XVIII, symptômes'),('04.2','sous-code hémoptysie')],'Hémoptysie (CIM-10-GM)','<p>Code de la toux avec émission de sang ; il exclut R05. Traité dans R04 — Hémorragie des voies respiratoires (P-02-Pneumologie).</p>')
a('F45.33',[('F','chapitre V, troubles mentaux et du comportement'),('45.33','sous-code trouble somatoforme de l’appareil respiratoire')],'Dysfonction neurovégétative somatoforme du système respiratoire (CIM-10-GM)','<p>Code de la toux psychogène, exclue de R05. L’ERS 2020 recommande de ne poser ce diagnostic qu’après un bilan complet.</p>')
a('R05.1',[('R','chapitre des symptômes'),('05.1','sous-code « toux aiguë » de la version américaine')],'Toux aiguë (CIM-10-CM américaine)','<p>Sous-code de la classification américaine CIM-10-CM ; il n’existe pas dans la CIM-10-GM utilisée en Suisse, où R05 n’a pas de sous-code.</p>')
a('R05.9',[('R','chapitre des symptômes'),('05.9','sous-code « toux, sans précision » de la version américaine')],'Toux sans précision (CIM-10-CM américaine)','<p>Sous-code de la classification américaine ; il n’existe pas dans la CIM-10-GM 2024.</p>')
a('MD12',[('MD12','code alphanumérique de la CIM-11, sans développement littéral (chapitre des symptômes et signes)')],'Toux (CIM-11)','<p>Catégorie de la toux dans la CIM-11 ; la correspondance exacte avec R05 et U69.6! reste à vérifier sur le navigateur de l’OMS.</p>')
a('TRPV1',[('T','Transient'),('R','Receptor'),('P','Potential'),('V','Vanilloid'),('1','type 1')],'Récepteur à potentiel transitoire de type vanilloïde 1','<p>Canal cationique des fibres C activé par la capsaïcine, la chaleur et les protons ; il transmet la sensation d’irritation et participe au déclenchement de la toux.</p>','r05-hyper')
a('TRPA1',[('T','Transient'),('R','Receptor'),('P','Potential'),('A','Ankyrin'),('1','type 1')],'Récepteur à potentiel transitoire de type ankyrine 1','<p>Canal cationique des fibres C activé par les irritants électrophiles de la fumée (acroléine) et des produits ménagers.</p>','r05-hyper')
a('TRPV4',[('T','Transient'),('R','Receptor'),('P','Potential'),('V','Vanilloid'),('4','type 4')],'Récepteur à potentiel transitoire de type vanilloïde 4','<p>Canal sensible à l’osmolarité et à l’étirement, cité par l’ERS 2020 parmi les récepteurs des terminaisons vagales.</p>')
a('ASIC',[('A','Acid-'),('S','Sensing'),('I','Ion'),('C','Channel')],'Canal ionique sensible aux acides','<p>Canal cationique activé par une baisse du pH ; il contribue à la toux déclenchée par l’acidité.</p>')
a('P2X3',[('P2','récepteur Purinergique de type 2'),('X','ionotrope (canal)'),('3','sous-type 3')],'Récepteur purinergique ionotrope P2X3','<p>Canal cationique activé par l’ATP, porté par les fibres C vagales. Cible du géfapixant.</p>','r05-d-gefa')
a('P2X2',[('P2','récepteur Purinergique de type 2'),('X','ionotrope (canal)'),('2','sous-type 2')],'Récepteur purinergique ionotrope P2X2','<p>Sous-unité qui forme avec P2X3 le récepteur hétéromérique P2X2/3 des fibres gustatives ; son blocage explique la dysgueusie du géfapixant.</p>','r05-d-gefa')
a('HARQ',[('H','Hull'),('A','Airway'),('R','Reflux'),('Q','Questionnaire')],'Hull Airway Reflux Questionnaire (questionnaire de Hull sur le reflux des voies aériennes)','<p>Questionnaire validé des symptômes de reflux des voies aériennes et d’hypersensibilité laryngée.</p>','r05-harq')
a('LCQ',[('L','Leicester'),('C','Cough'),('Q','Questionnaire')],'Leicester Cough Questionnaire (questionnaire de Leicester sur la toux)','<p>Questionnaire de qualité de vie spécifique de la toux ; différence minimale importante de 1,3 point selon l’ERS 2020.</p>','r05-lcq')
a('CQLQ',[('C','Cough-specific'),('Q','Quality of'),('L','Life'),('Q','Questionnaire')],'Cough-specific Quality of Life Questionnaire (questionnaire de qualité de vie spécifique de la toux)','<p>Second questionnaire validé de qualité de vie dans la toux chronique, cité par l’ERS 2020.</p>','r05-lcq')
a('COUGH-1',[('COUGH','nom de l’essai (toux en anglais)'),('1','premier essai de phase III')],'Essai COUGH-1','<p>Essai de phase III du géfapixant (730 patients, critère principal à 12 semaines) ; réduction de 18,5 % de la fréquence de la toux par rapport au placebo avec 45 mg deux fois par jour (Lancet 2022).</p>','r05-d-gefa')
a('COUGH-2',[('COUGH','nom de l’essai (toux en anglais)'),('2','second essai de phase III')],'Essai COUGH-2','<p>Essai de phase III du géfapixant (1314 patients, critère principal à 24 semaines) ; réduction de 14,6 % par rapport au placebo (Lancet 2022).</p>','r05-d-gefa')
a('SwissPAR',[('Swiss','suisse'),('P','Public'),('A','Assessment'),('R','Report')],'Swiss Public Assessment Report (rapport public d’évaluation de Swissmedic)','<p>Rapport publié par Swissmedic après l’autorisation d’un nouveau médicament ; il résume l’évaluation de la qualité, de la sécurité et de l’efficacité.</p>')
a('McGarvey',[('McGarvey','nom propre (Lorcan P. McGarvey, premier auteur)')],'McGarvey L. P.','<p>Premier auteur de la publication des essais COUGH-1 et COUGH-2 (Lancet 2022;399:909-923).</p>')
a('IMAO',[('I','Inhibiteur de la'),('M','MonoAmine'),('O','Oxydase')],'Inhibiteur de la monoamine oxydase','<p>Antidépresseur ou antiparkinsonien qui bloque la dégradation des monoamines ; son association au dextrométhorphane expose au syndrome sérotoninergique.</p>','r05-d-dxm')
